var SOL_LIKE_QUOTE_MINTS3 = Object.freeze([
  PublicKey9.default,
  NATIVE_MINT7,
  NATIVE_MINT_20223
]);
var STABLE_QUOTE_MINTS3 = Object.freeze([
  new PublicKey9("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v")
]);
function isSolLikeQuoteMint3(quoteMint) {
  return SOL_LIKE_QUOTE_MINTS3.some((mint) => mint.equals(quoteMint));
}
function isStableQuoteMint3(quoteMint) {
  return STABLE_QUOTE_MINTS3.some((mint) => mint.equals(quoteMint));
}
function computeFeesBps3({
  global: global2,
  feeConfig,
  mintSupply,
  virtualQuoteReserves,
  virtualTokenReserves,
  quoteMint,
  creatorFeeBps
}) {
  const schedule = scheduleFeesBps({
    global: global2,
    feeConfig,
    mintSupply,
    virtualQuoteReserves,
    virtualTokenReserves,
    quoteMint
  });
  if (!global2.creatorFeeConfigurable || creatorFeeBps == null || creatorFeeBps.isZero()) {
    return schedule;
  }
  return { protocolFeeBps: schedule.protocolFeeBps, creatorFeeBps };
}
function scheduleFeesBps({
  global: global2,
  feeConfig,
  mintSupply,
  virtualQuoteReserves,
  virtualTokenReserves,
  quoteMint
}) {
  if (feeConfig != null) {
    const marketCap = bondingCurveMarketCap({
      mintSupply,
      virtualQuoteReserves,
      virtualTokenReserves
    });
    return selectCurveFeeSchedule({
      feeConfig,
      quoteMint: quoteMint ?? PublicKey9.default,
      marketCap
    });
  }
  return {
    protocolFeeBps: global2.feeBasisPoints,
    creatorFeeBps: global2.creatorFeeBasisPoints
  };
}
function selectCurveFeeSchedule({
  feeConfig,
  quoteMint,
  marketCap
}) {
  if (isSolLikeQuoteMint3(quoteMint)) {
    return calculateFeeTier3({ feeTiers: feeConfig.feeTiers, marketCap });
  }
  if (isStableQuoteMint3(quoteMint)) {
    return calculateFeeTier3({
      feeTiers: feeConfig.stableFeeTiers.length > 0 ? feeConfig.stableFeeTiers : feeConfig.feeTiers,
      marketCap
    });
  }
  return isZeroFees3(feeConfig.exoticFlatFees) ? feeConfig.flatFees : feeConfig.exoticFlatFees;
}
function isZeroFees3({ lpFeeBps, protocolFeeBps, creatorFeeBps }) {
  return lpFeeBps.isZero() && protocolFeeBps.isZero() && creatorFeeBps.isZero();
}
function calculateFeeTier3({
  feeTiers,
  marketCap
}) {
  if (feeTiers.length === 0) {
    throw new Error("Fee tiers cannot be empty");
  }
  const firstTier = feeTiers[0];
  if (marketCap.lt(firstTier.marketCapLamportsThreshold)) {
    return firstTier.fees;
  }
  for (const tier of feeTiers.slice().reverse()) {
    if (marketCap.gte(tier.marketCapLamportsThreshold)) {
      return tier.fees;
    }
  }
  return firstTier.fees;
}
function getFeeRecipient3(global2, mayhemMode) {
  const [primary, ...others] = mayhemMode ? [global2.reservedFeeRecipient, ...global2.reservedFeeRecipients] : [global2.feeRecipient, ...global2.feeRecipients];
  const feeRecipients = [primary, ...others].filter(
    (key) => !key.equals(PublicKey9.default)
  );
  if (feeRecipients.length === 0) {
    return primary;
  }
  return feeRecipients[Math.floor(Math.random() * feeRecipients.length)];
}
